local function lookup(ranges, cp, default)
  local lo, hi = 1, #ranges
  while lo <= hi do
    local mid = math.floor((lo + hi) / 2)
    local r = ranges[mid]
    if cp < r[1] then hi = mid - 1 elseif cp > r[2] then lo = mid + 1 else return r[3] end
  end
  return default
end
function U.bidi(cp) return lookup(bidi_ranges, cp, "L") end
function U.is_mark(cp) return lookup(mark_ranges, cp, 0) == 1 end
function U.combining(cp) return lookup(ccc_ranges, cp, 0) end
function U.script(cp) return lookup(script_ranges, cp, "Zyyy") end
function U.joining_type(cp) return lookup(joining_ranges, cp, "U") end
function U.indic_syllabic(cp) return lookup(indic_syllabic_ranges, cp, "Other") end
function U.indic_positional(cp) return lookup(indic_positional_ranges, cp, "NA") end
function U.mirror(cp) return mirror[cp] end
function U.indic_decompose(cp) return indic_decomp[cp] end
return U
